B.YU=new A.b1("kanun_06",B.dd,"S\xfcresinde kanun yoluna ba\u015fvurulmayan bir karar bak\u0131m\u0131ndan sonu\xe7 nedir?",B.RB,1,"Kanun yolu s\xfcresi i\xe7inde ba\u015fvurulmazsa veya kanun yolu kapal\u0131ysa karar kesinle\u015fir; kesinle\u015fen karar icra edilebilir ve kesin h\xfck\xfcm (res judicata) etkisi do\u011furur.")
